import {
    LogicWrapper,
    MakeLogicType,
    actions,
    afterMount,
    kea,
    key,
    listeners,
    path,
    props,
    reducers,
    selectors,
} from 'kea'
import { loaders } from 'kea-loaders'

import * as api from '../generated/api'
import type { ConversionRecommendationStateApi } from '../generated/api.schemas'

export interface ConversionRecommendationsProps {
    projectId: number
    enabled: boolean
    userId?: string
}

const POLL_INTERVAL_MS = 5000

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversionRecommendationsLogicValues {
    error: string | null
    isAnalyzing: boolean
    state: ConversionRecommendationStateApi | null
    stateLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversionRecommendationsLogicActions {
    loadRecommendations: (_: void) => void
    loadRecommendationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRecommendationsSuccess: (
        state: ConversionRecommendationStateApi,
        payload?: void
    ) => {
        state: ConversionRecommendationStateApi
        payload?: void
    }
    requestAnalysis: (refresh: boolean) => {
        refresh: boolean
    }
    startAnalysis: ({ refresh }: { refresh: boolean }) => {
        refresh: boolean
    }
    startAnalysisFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    startAnalysisSuccess: (
        state: ConversionRecommendationStateApi,
        payload?: {
            refresh: boolean
        }
    ) => {
        state: ConversionRecommendationStateApi
        payload?: {
            refresh: boolean
        }
    }
    syncPolling: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface conversionRecommendationsLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        isAnalyzing: (state: ConversionRecommendationStateApi | null) => boolean
    }
}

export type conversionRecommendationsLogicType = MakeLogicType<
    conversionRecommendationsLogicValues,
    conversionRecommendationsLogicActions,
    ConversionRecommendationsProps,
    conversionRecommendationsLogicMeta
>

export const conversionRecommendationsLogic: LogicWrapper<conversionRecommendationsLogicType> =
    kea<conversionRecommendationsLogicType>([
        props({} as ConversionRecommendationsProps),
        key(({ projectId, enabled, userId }) => `${userId}:${projectId}:${enabled}`),
        path((key) => ['products', 'marketing_analytics', 'setup', 'conversionRecommendationsLogic', key]),
        actions({ requestAnalysis: (refresh: boolean) => ({ refresh }), syncPolling: true }),
        loaders(({ props }) => ({
            state: [
                null as ConversionRecommendationStateApi | null,
                {
                    loadRecommendations: async (_: void, breakpoint) => {
                        const state = await api.marketingAnalyticsConversionRecommendationsRetrieve(
                            String(props.projectId)
                        )
                        breakpoint()
                        return state
                    },
                    startAnalysis: async ({ refresh }: { refresh: boolean }, breakpoint) => {
                        const state = await api.marketingAnalyticsConversionRecommendationsStartCreate(
                            String(props.projectId),
                            { refresh }
                        )
                        breakpoint()
                        return state
                    },
                },
            ],
        })),
        reducers({
            error: [
                null as string | null,
                {
                    loadRecommendationsSuccess: () => null,
                    startAnalysisSuccess: () => null,
                    loadRecommendationsFailure: () =>
                        'Could not load recommendations. Retry loading to check the latest results.',
                    startAnalysisFailure: () =>
                        'Could not confirm the analysis started. Reload its status before trying again.',
                },
            ],
        }),
        selectors({
            isAnalyzing: [
                (s) => [s.state],
                (state: ConversionRecommendationStateApi | null): boolean =>
                    state?.latest_run?.status === 'pending' || state?.latest_run?.status === 'running',
            ],
        }),
        listeners(({ actions, values, cache, props }) => ({
            requestAnalysis: ({ refresh }) => {
                if (props.enabled && values.state?.can_generate && !values.stateLoading && !values.isAnalyzing) {
                    actions.startAnalysis({ refresh })
                }
            },
            loadRecommendationsSuccess: ({ state }) => {
                if (!state.latest_run && state.can_generate && !cache.initialAttempted) {
                    cache.initialAttempted = true
                    actions.requestAnalysis(false)
                }
                actions.syncPolling()
            },
            startAnalysisSuccess: () => actions.syncPolling(),
            loadRecommendationsFailure: () => cache.disposables.dispose('analysisPoll'),
            startAnalysisFailure: () => cache.disposables.dispose('analysisPoll'),
            syncPolling: () => {
                cache.disposables.dispose('analysisPoll')
                if (values.isAnalyzing) {
                    cache.disposables.add(() => {
                        const timer = setInterval(() => {
                            if (!values.stateLoading) {
                                actions.loadRecommendations()
                            }
                        }, POLL_INTERVAL_MS)
                        return () => clearInterval(timer)
                    }, 'analysisPoll')
                }
            },
        })),
        afterMount(({ actions, props }) => {
            if (props.enabled && props.projectId > 0) {
                actions.loadRecommendations()
            }
        }),
    ])
